<?php /** @var array $periods */ ?>
<div class="page__section flex flex-col gap-4"><div class="card"><div class="card__header"><span class="card__title">Buat Periode Pengajuan</span></div><div class="card__body"><form method="post" action="<?= base_url('bhp/periods/store') ?>" style="display:flex;flex-wrap:nowrap;align-items:end;gap:.5rem;overflow-x:auto;padding-bottom:.25rem"><?= csrf_field() ?><input class="input" style="min-width:18rem" name="nama_periode" placeholder="Pengajuan BHP September 2026" required><input class="input" type="datetime-local" name="tanggal_mulai" required><input class="input" type="datetime-local" name="tanggal_selesai" required><button class="button button--primary">Simpan Periode</button></form></div></div><div class="card"><div class="card__header"><span class="card__title">Daftar Periode</span></div><div class="card__body"><div class="table-responsive"><table class="table"><thead><tr><th>Nama</th><th>Mulai</th><th>Selesai</th><th>Status</th></tr></thead><tbody><?php if (empty($periods)): ?><tr><td colspan="4"><?= view('partials/empty_table_state', ['message' => 'Belum ada periode pengajuan.']) ?></td></tr><?php endif; ?><?php foreach ($periods as $period): $active = time() >= strtotime($period['tanggal_mulai']) && time() <= strtotime($period['tanggal_selesai']); ?><tr><td><?= esc($period['nama_periode']) ?></td><td><?= esc($period['tanggal_mulai']) ?></td><td><?= esc($period['tanggal_selesai']) ?></td><td><span class="badge badge--soft badge--<?= $active ? 'success' : 'secondary' ?>"><?= $active ? 'Aktif' : 'Tidak Aktif' ?></span></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
